import pandas as pd

def best_month(long):
    wide = long.pivot(index="date", columns="ticker", values="close")
    me = wide.resample("ME").last()
    ret = me.pct_change().dropna()
    return {t: ret[t].idxmax().strftime("%Y-%m") for t in ret.columns}

