import pandas as pd

def toy():
    """Two shares over nine trading days, one row per share per day, share by share."""
    days = pd.bdate_range("2024-09-02", periods=9)
    closes = {"KTX": [40, 41, 44, 43, 42, 45, 41, 43, 46],
              "LMN": [80, 78, 77, 79, 76, 75, 78, 80, 79]}
    rows = [(d, t, float(c[i])) for t, c in closes.items() for i, d in enumerate(days)]
    return pd.DataFrame(rows, columns=["date", "ticker", "close"])

def share(out, df, t):
    """out on share t's rows of df, in date order, rounded to 6 places, None for NaN."""
    rows = df[df["ticker"] == t].sort_values("date").index
    return [None if x != x else round(float(x), 6) for x in out.loc[rows]]

def panel(seed, n_days=60, n_shares=5):
    """Seeded closes for n_shares over n_days, about one day in twenty missing per share, rows shuffled."""
    x = seed
    def u():
        nonlocal x
        x = (6364136223846793005 * x + 1442695040888963407) % 2 ** 64
        return (x >> 11) / 2 ** 53
    days = pd.bdate_range("2024-01-02", periods=n_days)
    rows = []
    for j in range(n_shares):
        p = 20 + 80 * u()
        for d in days:
            p *= 1 + 0.04 * (u() - 0.5)
            if u() >= 0.05:
                rows.append((d, f"S{j}", round(p, 2)))
    df = pd.DataFrame(rows, columns=["date", "ticker", "close"])
    order = sorted(range(len(df)), key=lambda i: u())
    return df.iloc[order].reset_index(drop=True)
